WITH enriched AS (SELECT *, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, LAST_VALUE(country, TRUE) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_2, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_3 FROM sessions WHERE browser IN ('Chrome', 'Safari', 'Edge')) SELECT country, DATE_TRUNC('MONTH', started_at) AS activity_month, MIN(started_at) AS started_at, SORT_ARRAY(COLLECT_SET(device)) AS device_list, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM enriched GROUP BY country, DATE_TRUNC('MONTH', started_at) HAVING distinct_customer_ids > 1;
